    enterprise: { title: "एंटरप्राइज़ सुविधाएँ - WorkCoPilot by AdmireVeda", description: "WorkCoPilot आपकी कंपनी को सीखता है: अपनी प्रक्रियाएँ, गाइड और डेटा अपलोड करें, और यह आपके लोगों को उनकी अपनी स्क्रीन पर हर सटीक कदम पर साथ देता है, ठीक वैसे जैसे आपकी कंपनी काम करती है। आपके संगठन के लिए निजी। साथ ही डिवाइस पर रिडैक्शन, ऑडिट लॉग, DLP गवर्नेंस, SIEM अलर्ट, SSO, अनुपालन साक्ष्य रिपोर्ट, नेतृत्व के लिए ROI, व्हाइट-लेबल और प्रति-कंपनी बिलिंग।" },
